def metric(data: pd.DataFrame) -> float:
    import numpy as np

    a = np.stack(data['option_a_ratings'].values)
    b = np.stack(data['option_b_ratings'].values)

    preds = []
    for i in range(len(data)):
        p = -1
        for j in range(4):
            if a[i, j] > b[i, j]:
                p = 0
                break
            elif b[i, j] > a[i, j]:
                p = 1
                break
        preds.append(p)

    preds = np.array(preds)
    return float(np.mean(data['response'] == preds))

